\label{thm-Kisin}
		If $R_{\bar\rho}^{\square,\psi}(\mathbf{w},\tau)$ is nonzero, then it is a reduced,
		equi-dimensional, complete Noetherian local $\mathcal{O}$-flat algebra, such that $R_{\bar\rho}^{\square,\psi}(\mathbf{w},\tau)[1/\varpi]$ is regular.

\label{lem-rep1}
		Suppose that $m\geq1$. Put $C(m)=\frac{p^{m-1}-1}{p-1}$. As an $\mathbb{F}[\bar T]$-module, we have
		\begin{equation}
			\label{eq-lem1}
			V:=\operatorname{Ind}_{\mathrm{Iw}_m}^{\mathrm{Iw}}\mathbf1
			\simeq\bigoplus_{i=0}^{p-2}
			(\omega^i\otimes\omega^{p-1-i})^{\oplus m(i)},
		\end{equation}
		where $m(0)=C(m)+1$, and $m(i\neq0):=m(i)=C(m)$ for $1\leq i\leq p-2$.

\label{prop-slope-map}
		There exists a rigid analytic map
		\[
		\lambda:=\lambda_{(\bar\rho,\psi,\tau,\mathbf{w})}:
		\mathcal{X}=\bigl(\operatorname{Spf} R_{\bar\rho}^{\square,\psi}(\mathbf{w},\tau)\bigr)^{\mathrm{rig}}
		\longrightarrow\mathbb{A}^{1,\mathrm{an}}
		\]
		such that, for every closed point $x\in\mathcal{X}$, $k_2-v_p(\lambda(x))$ is equal to the slope $\mathfrak{s}(x)$ of $\rho_x$.

\label{cor-naive-lower-bound}
		Let $\mathcal{X}^{\mathrm{cl}}$ denote the set of closed points of $\mathcal{X}$.
		Suppose that the number of distinct slopes occurring in $\mathcal{X}$, i.e.
		$\#(\{\mathfrak{s}(x):x\in\mathcal{X}^{\mathrm{cl}}\})$, is finite.
		Then $\mathfrak{s}(x)$ is constant on each connected (equivalently,
		irreducible) component of $\mathcal{X}$, and
		\begin{equation}
			\label{eq-proof2}
			e\bigl(R_{\bar\rho}^{\square,\psi}(\mathbf{w},\tau)/\varpi\bigr)
			\geq
			\#\left\{\begin{array}{c}
				\text{connected components}\\
				\text{of }\mathcal{X}
			\end{array}\right\}
			\geq\#(\{\mathfrak{s}(x):x\in\mathcal{X}^{\mathrm{cl}}\}).
		\end{equation}

\label{def-halo-slopes}
		For $\varepsilon=\omega^{-s_\varepsilon+b}\times\omega^{s_\varepsilon+a+b}$, set
		$
		\eta_1:=\min\{s_\varepsilon,\{s_\varepsilon+a\}\}$, and
		$\eta_2:=\max\{s_\varepsilon,\{s_\varepsilon+a\}\}$.
		Define a sequence $(a_n)_{n\geq1}$ by
		\[
		a_{2\ell+1}:=\eta_1+\ell(p-1),
		\quad\textrm{and}\quad
		a_{2\ell+2}:=\eta_2+\ell(p-1)
		\qquad(\ell\geq0).
		\]
		For $n\geq1$, the $n$th \emph{Hodge ratio} is
		$
		\lambda_n^{(\varepsilon)}:=a_n-\lfloor a_n/p\rfloor$.
		The \emph{Newton ratios} $\mathfrak{s}_n^{(\varepsilon)}$ are defined by the
		following formulas, for $n\geq0$.
		If $a+s_\varepsilon<p-1$, set
		\begin{equation}
			\mathfrak{s}_{n+1}^{(\varepsilon)}-\lambda_{n+1}^{(\varepsilon)}
			=\begin{cases}
				1,& n-2s_\varepsilon\equiv1,3,\dots,2a+1\pmod{2p},\\
				-1,& n-2s_\varepsilon\equiv2,4,\dots,2a+2\pmod{2p},\\
				0,&\text{otherwise}.
			\end{cases}
		\end{equation}
		If $a+s_\varepsilon\geq p-1$, set
		\begin{equation}
			\mathfrak{s}_{n+1}^{(\varepsilon)}-\lambda_{n+1}^{(\varepsilon)}
			=\begin{cases}
				1,& n-2s_\varepsilon\equiv2,4,\dots,2a+2\pmod{2p},\\
				-1,& n-2s_\varepsilon\equiv3,5,\dots,2a+3\pmod{2p},\\
				0,&\text{otherwise}.
			\end{cases}
		\end{equation}

\label{prop-crystabelline-slopes}
		Assume that $p\geq11$.
		Let $\mathcal{X}=\bigl(\operatorname{Spf} R_{\bar\rho}^{\square,\psi}(\mathbf{w},\tau)\bigr)^{\mathrm{rig}}$
		and $k_0:=\{k_2-k_1-1\}$.
		\begin{enumerate}
			\item A slope $\mathfrak{s}\in(0,k_2-k_1)$ occurs in $\mathcal{X}$ if and
			only if it is a slope of $\operatorname{NP}(G_\sigma^{(\varepsilon)}(w_*,-))$.

			\item Suppose that $\bar\rho$ is non-split. Then:
			\begin{enumerate}
				\item the slope $0$ occurs in $\mathcal{X}$ if and only if $s_\varepsilon=0$;
				\item the slope $k_2-k_1$ occurs in $\mathcal{X}$ if and only if
				$k_0=\{s_\varepsilon+a\}$.
			\end{enumerate}

			\item Suppose that $\bar\rho$ is split. Then:
			\begin{enumerate}
				\item the slope $0$ occurs in $\mathcal{X}$ if and only if $s_\varepsilon=0$
				or $s'_\varepsilon=\{s_\varepsilon+a+1\}=0$;
				\item the slope $k_2-k_1$ occurs in $\mathcal{X}$ if and only if
				$k_0=\{s_\varepsilon+a\}$ or $k_0=\{s'_\varepsilon+a'\}=\{s_\varepsilon-1\}$.
			\end{enumerate}
		\end{enumerate}

\label{def-decomp-of-Min(R)}
		Write $R=R_{\bar\rho}^{\square,\psi}(\mathbf{w},\tau)$.
		We define \begin{equation}
			\label{eq-decomp-of-Min(R)}
			\mathfrak{a}_\mathfrak{s}
			:=
			\bigcap_{\substack{x\in\mathcal{X}^{\mathrm{cl}}\\ \mathfrak{s}(x)=\mathfrak{s}}}
			(\mathfrak{m}_x
			\cap R)\quad\textrm{and}\quad\Sigma_{\mathfrak{s}}(\bar\rho):=\{\mathfrak{p}\in\operatorname{Min}(R):\mathfrak{a}_\mathfrak{s}\subseteq\mathfrak{p}\}.
		\end{equation} Then we have the decomposition $\operatorname{Min}(R_{\bar\rho}^{\square,\psi}(\mathbf{w},\tau))=\bigsqcup_{\mathfrak{s}\in\{\mathfrak{s}(x):x\in\mathcal{X}^\mathrm{cl}\}}\Sigma_\mathfrak{s}(\bar\rho)$. For simplicity, we also use $\Sigma_{(0,k_2-k_1)}(\bar\rho)$ to denote the union $\cup_{\mathfrak{s}\in(0,k_2-k_1)}\Sigma_{\mathfrak{s}}(\bar\rho)$.

\label{thm-main-thm-split}
		Assume that $p\geq11$.
		Keep the notation of Definition~\ref{def-decomp-of-Min(R)}.
		Let $\bar\rho$ be a reducible, split, and very generic local representation. Let $\tau$ be a wildly ramified principal series type. Write $R=R_{\bar\rho}^{\square,\psi}(\mathbf{w},\tau)$, and let $e'(\operatorname{Spf}(R)^\mathrm{rig})$ denote the number of distinct crystabelline slopes of $\operatorname{Spf}(R)^\mathrm{rig}$. Then $\operatorname{Spec} R$ has exactly $e'(\operatorname{Spf}(R)^\mathrm{rig})$ irreducible components. In particular, each $\mathfrak{a}_\mathfrak{s}$ in the decomposition \eqref{eq-decomp-of-Min(R)} is minimal.

		Moreover, we have the following statements about Breuil--M\'ezard multiplicities. For $\mathfrak{p}\in\operatorname{Min}(R)$, we write $R(\mathfrak{p}):=R/\mathfrak{p}$.
		\begin{enumerate}
			\item If $\mathfrak{p}\in\Sigma_\mathfrak{s}(\bar\rho)$ for some $\mathfrak{s}\in(0,k_2-k_1)$, then $e(R(\mathfrak{p})/\varpi)=2$.
			\item If $\mathfrak{p}\in\Sigma_\mathfrak{s}(\bar\rho)$ for some $\mathfrak{s}\in\{0,k_2-k_1\}$, then $e(R(\mathfrak{p})/\varpi)=1$ and $R(\mathfrak{p})$ is a formal power series ring over $\mathcal{O}$.
		\end{enumerate}

\label{lem-relation-slope-and-reducible-type}
		Let $A=R^{\operatorname{ver}}(\mathbf{w},\tau)$, and let $\mathfrak{p}\in\operatorname{Min}(A)$. We also use $I_*^{\operatorname{ver}}$ to denote the image of this ideal in $A$.  
		\begin{enumerate}
			\item 
			We have  $\mathfrak{p}\in V(I_{\operatorname{irr}}^{\operatorname{ver}})$ if and only if $\mathfrak{p}\in\Sigma_{(0,k_2-k_1)}(\bar\rho_0)$, in which case $c\notin\mathfrak{p}$.
			\item 
			If $\mathfrak{p}\in\Sigma_\mathfrak{s}(\bar\rho_0)$ for $\mathfrak{s}\in\{0,k_2-k_1\}$, then we have $\mathfrak{p}\in V(I_i^{\operatorname{ver}})\setminus V(I_{3-i}^{\operatorname{ver}})$, where $i\in\{1,2\}$ is given by
			\begin{equation}
				\label{eq-4}
				i=\begin{cases}
					1,&\textrm{if } \mathfrak{s}=0,\textrm{ and } s_\varepsilon=0,\\
					2,&\textrm{if } \mathfrak{s}=0,\textrm{ and } s'_\varepsilon=0,\\
					1,&\textrm{if } \mathfrak{s}=k_2-k_1,\textrm{ and } \{s_\varepsilon+a\}=\{k_2-k_1-1\},\\
					2,&\textrm{if } \mathfrak{s}=k_2-k_1,\textrm{ and } \{s'_\varepsilon+a'\}=\{k_2-k_1-1\}.
				\end{cases}
			\end{equation}
		\end{enumerate}

\label{lem-minimal-primes}
		Let $A$ be a ring and let $I,J\subseteq A$ be ideals. 
		\begin{enumerate}
			\item If
			$\mathfrak p$ is minimal over $I\cap J$ and $\mathfrak p\in V(I)$, then $\mathfrak p$ is minimal over $I$.
			\item If
			$\mathfrak p$ is minimal over $I$ and $\mathfrak p\in V(I)-V(J)$, then $\mathfrak p$ is minimal over $I\cap J$.
		\end{enumerate}
